:root {
  --bg: #2b2b3c;
  --card: #3c3c54;
  --accent: #f0c330;
  --accent-hover: #ffd95a;
  --text: #f0f0f0;
  --text-muted: #a0a0b8;
  --high: #e74c3c;
  --medium: #f39c12;
  --low: #2ecc71;
  --border: #5a5a78;
  --shadow: rgba(0, 0, 0, 0.4);
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background-image: linear-gradient(45deg, #222233 25%, transparent 25%),
                    linear-gradient(-45deg, #222233 25%, transparent 25%),
                    linear-gradient(45deg, transparent 75%, #222233 75%),
                    linear-gradient(-45deg, transparent 75%, #222233 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
}

.app {
  width: 100%;
  max-width: 520px;
  background: var(--card);
  border: 3px solid var(--border);
  box-shadow: 6px 6px 0 var(--shadow);
  padding: 24px 20px;
  border-radius: 0;
}

h1 {
  font-size: 1.8rem;
  text-align: center;
  margin-bottom: 24px;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--shadow);
  letter-spacing: 2px;
}

.task-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 20px;
}

.input-row {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.input-row input {
  flex: 1 1 200px;
  min-width: 0;
  padding: 10px 12px;
  font-family: var(--font);
  font-size: 1rem;
  background: var(--bg);
  border: 2px solid var(--border);
  color: var(--text);
  outline: none;
}

.input-row input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}

.input-row select {
  padding: 10px 12px;
  font-family: var(--font);
  font-size: 1rem;
  background: var(--bg);
  border: 2px solid var(--border);
  color: var(--text);
  cursor: pointer;
  outline: none;
}

.input-row select:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}

.pixel-btn {
  padding: 10px 20px;
  font-family: var(--font);
  font-size: 1rem;
  font-weight: bold;
  background: var(--accent);
  color: var(--bg);
  border: 3px solid var(--border);
  box-shadow: 3px 3px 0 var(--shadow);
  cursor: pointer;
  transition: background 0.1s, transform 0.1s, box-shadow 0.1s;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.pixel-btn:hover {
  background: var(--accent-hover);
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 var(--shadow);
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.filters {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.filter-btn {
  flex: 1;
  padding: 8px 12px;
  font-family: var(--font);
  font-size: 0.95rem;
  background: var(--bg);
  color: var(--text-muted);
  border: 2px solid var(--border);
  cursor: pointer;
  transition: background 0.1s, color 0.1s, border-color 0.1s;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.filter-btn:hover {
  background: var(--border);
  color: var(--text);
}

.filter-btn.active {
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent);
  font-weight: bold;
}

.filter-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.filter-btn:active {
  transform: translate(1px, 1px);
}

.task-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.task-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
  background: var(--bg);
  border: 2px solid var(--border);
  transition: border-color 0.2s, opacity 0.2s;
  flex-wrap: wrap;
}

.task-item.completed {
  opacity: 0.6;
}

.task-item.completed .task-text {
  text-decoration: line-through;
  color: var(--text-muted);
}

.priority-indicator {
  width: 12px;
  height: 12px;
  border-radius: 0;
  flex-shrink: 0;
  border: 2px solid var(--border);
}

.priority-high .priority-indicator {
  background: var(--high);
}
.priority-medium .priority-indicator {
  background: var(--medium);
}
.priority-low .priority-indicator {
  background: var(--low);
}

.task-text {
  flex: 1;
  word-break: break-word;
  font-size: 1rem;
  min-width: 0;
}

.task-actions {
  display: flex;
  gap: 6px;
  flex-shrink: 0;
}

.task-actions button {
  padding: 6px 10px;
  font-family: var(--font);
  font-size: 0.85rem;
  border: 2px solid var(--border);
  background: var(--card);
  color: var(--text);
  cursor: pointer;
  transition: background 0.1s, color 0.1s;
  text-transform: uppercase;
}

.task-actions button:hover {
  background: var(--border);
}

.task-actions button:active {
  transform: translate(1px, 1px);
}

.task-actions button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.task-actions .delete-btn:hover {
  background: var(--high);
  color: #fff;
}

.empty-message {
  text-align: center;
  color: var(--text-muted);
  padding: 24px 0;
  font-size: 1rem;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .app {
    padding: 16px 12px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .task-item {
    padding: 10px 8px;
  }
  .task-actions button {
    padding: 5px 8px;
    font-size: 0.8rem;
  }
}

(function() {
  'use strict';

  const STORAGE_KEY = 'pixel-priority-tasks';

  const taskForm = document.getElementById('task-form');
  const taskInput = document.getElementById('task-input');
  const prioritySelect = document.getElementById('priority-select');
  const taskList = document.getElementById('task-list');
  const emptyMessage = document.getElementById('empty-message');
  const filterButtons = document.querySelectorAll('.filter-btn');

  let tasks = loadTasks();
  let currentFilter = 'all';

  function loadTasks() {
    try {
      const data = localStorage.getItem(STORAGE_KEY);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      return [];
    }
  }

  function saveTasks() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
    } catch (e) {
      // localStorage may be unavailable; silently ignore
    }
  }

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
  }

  const priorityOrder = { high: 0, medium: 1, low: 2 };

  function sortTasks(list) {
    return list.slice().sort((a, b) => {
      const pa = priorityOrder[a.priority] ?? 1;
      const pb = priorityOrder[b.priority] ?? 1;
      if (pa !== pb) return pa - pb;
      return a.id.localeCompare(b.id);
    });
  }

  function render() {
    const filtered = tasks.filter(task => {
      if (currentFilter === 'active') return !task.completed;
      if (currentFilter === 'completed') return task.completed;
      return true;
    });

    const sorted = sortTasks(filtered);

    taskList.innerHTML = '';

    if (sorted.length === 0) {
      emptyMessage.hidden = false;
    } else {
      emptyMessage.hidden = true;
    }

    sorted.forEach(task => {
      const li = document.createElement('li');
      li.className = 'task-item priority-' + task.priority + (task.completed ? ' completed' : '');
      li.dataset.id = task.id;

      const indicator = document.createElement('span');
      indicator.className = 'priority-indicator';
      indicator.setAttribute('aria-hidden', 'true');

      const text = document.createElement('span');
      text.className = 'task-text';
      text.textContent = task.text;

      const actions = document.createElement('div');
      actions.className = 'task-actions';

      const toggleBtn = document.createElement('button');
      toggleBtn.type = 'button';
      toggleBtn.className = 'toggle-btn';
      toggleBtn.textContent = task.completed ? 'Undo' : 'Done';
      toggleBtn.setAttribute('aria-label', (task.completed ? 'Mark as active: ' : 'Mark as completed: ') + task.text);
      toggleBtn.addEventListener('click', () => toggleTask(task.id));

      const deleteBtn = document.createElement('button');
      deleteBtn.type = 'button';
      deleteBtn.className = 'delete-btn';
      deleteBtn.textContent = 'Del';
      deleteBtn.setAttribute('aria-label', 'Delete task: ' + task.text);
      deleteBtn.addEventListener('click', () => deleteTask(task.id));

      actions.appendChild(toggleBtn);
      actions.appendChild(deleteBtn);

      li.appendChild(indicator);
      li.appendChild(text);
      li.appendChild(actions);

      taskList.appendChild(li);
    });
  }

  function addTask(text, priority) {
    tasks.push({
      id: generateId(),
      text: text.trim(),
      priority: priority,
      completed: false
    });
    saveTasks();
    render();
  }

  function toggleTask(id) {
    const task = tasks.find(t => t.id === id);
    if (task) {
      task.completed = !task.completed;
      saveTasks();
      render();
    }
  }

  function deleteTask(id) {
    tasks = tasks.filter(t => t.id !== id);
    saveTasks();
    render();
  }

  taskForm.addEventListener('submit', function(e) {
    e.preventDefault();
    const text = taskInput.value.trim();
    if (!text) return;
    addTask(text, prioritySelect.value);
    taskInput.value = '';
    taskInput.focus();
  });

  filterButtons.forEach(btn => {
    btn.addEventListener('click', function() {
      currentFilter = this.dataset.filter;
      filterButtons.forEach(b => {
        const active = b === this;
        b.classList.toggle('active', active);
        b.setAttribute('aria-pressed', active ? 'true' : 'false');
      });
      render();
    });
  });

  render();
})();
